import { isListedThreadLineage, PROVIDER_SEND_TURN_MAX_FILE_BYTES, ThreadId } from "@t3tools/contracts";
import { threadTranscriptHeader } from "@t3tools/shared/threadTranscript";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import * as Orchestrator from "./Orchestrator.session-api.ts";
import * as ServerEnvironment from "../environment/ServerEnvironment.session-port.ts";
import { projectedRowEncodedBytes } from "./threadHistoryPaging.ts";
import { projectTurnItemForDetail } from "./WireProjection.ts";
import * as LegacyV1ThreadImporter from "./legacy/LegacyV1ThreadImporter.ts";

export type ThreadReadShape = Pick<ThreadManagementServiceShape, "ensureLegacyTranscript" | "searchThreadStream" | "searchThread" | "getThreadHistoryPage" | "getTimelinePage" | "getMessageCount" | "getTurnItem" | "getThreadRecords" | "getThreadProjection" | "getCheckpointContext" | "getThreadSnapshot" | "getThreadTranscript" | "getThreadSnapshotWindow" | "getProjectThreadRecords" | "getAgentAwarenessSnapshot" | "getShellSnapshot" | "listActiveSubagentThreadIds" | "countThreads" | "listActiveShellIndex" | "listOlderSettledThreads" | "readShellSnapshot" | "getThreadShell" | "listAppOwnedChildThreadIds" | "getThreadTitles" | "listProjectThreads" | "getThreadEventSequence" | "streamStoredEvents" | "streamStoredEventsFrom" | "streamDomainEvents">;
export const makeThreadReads = (
  orchestrator: OrchestratorReadShape,
  legacyImporter: LegacyV1ThreadImporter.LegacyV1ThreadImporter["Service"],
): ThreadReadShape => {

