const reads = makeThreadReads(orchestrator, legacyImporter);
const { ensureLegacyTranscript, getThreadProjection, getCheckpointContext, getThreadSnapshot, getThreadTranscript, getThreadSnapshotWindow, getProjectThreadRecords, listProjectThreads } = reads;
const ensureProjectionTranscript = (threadId: ThreadId) => ensureLegacyTranscript(threadId).pipe(Effect.mapError((cause) => new Orchestrator.OrchestratorProjectionError({ threadId, cause })));

